            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "العدل أساس الملك، وبغيره لا تقوم حضارة ولا تزدهر أمة.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الوسطية هي الطريق الأمثل، والاعتدال هو قوام الأمور.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الحياة قصيرة، فلنجعل منها عملاً صالحاً يبقى أثره.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "التعصب الأعمى يقود إلى الدمار، والحوار البناء هو سبيل التقدم.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "لا تخف من قول الحق، ولا ترتعب من مواجهة الباطل.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الأمل شعلة لا تنطفئ في قلب المؤمن، تدفعه إلى الأمام رغم الصعاب.", Author = "الغزالي" },
