            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الإنسان الحر هو من يملك زمام نفسه، ويتحكم في أهوائه.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الحكمة ضالة المؤمن، أينما وجدها أخذها.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "التسامح ليس ضعفاً، بل هو قوة إرادة، وقدرة على تجاوز الأخطاء.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الحق لا يعرف بالرجال، بل الرجال يعرفون بالحق.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "المسؤولية تبدأ من داخل النفس، وتنتهي بإصلاح المجتمع.", Author = "الغزالي" },
