            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الكلمة الطيبة صدقة، والفعل الحسن عبادة.", Author = "الغزالي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/الغزالي", Text = "الإصلاح يبدأ بالنفس، ثم بالأسرة، ثم بالمجتمع.", Author = "الغزالي" },
